import { ColumnMinInstance } from '../../types/internal-table-types.js';

function hasStringHeader(
  column: ColumnMinInstance,
): column is ColumnMinInstance {
  return column.Header !== undefined && typeof column.Header === 'string';
}

function filterColumn(column: ColumnMinInstance, activeFilterValue: string) {
  if (column.id.toLocaleLowerCase().includes(activeFilterValue)) {
    return true;
  }

  if (
    hasStringHeader(column) &&
    column.Header.toLocaleLowerCase().includes(activeFilterValue)
  ) {
    return true;
  }
  return false;
}

/* Filters columns incl. parent columns by a given filter string */
export function filterColumnsByString(
  columns: ColumnMinInstance[],
  filterString: string,
) {
  return columns.filter((column) => {
    const shouldFilterColumn = filterColumn(column, filterString);
    const parent = column.parent;

    const shouldFilterParent = parent
      ? filterColumn(parent, filterString)
      : false;

    return shouldFilterColumn || shouldFilterParent;
  });
}
